package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class SectionConfigTest {
 @Test public void noSectionsOrFoldersAreCreatedImplicitly(){SectionConfig c=new SectionConfig();assertTrue(c.sections.isEmpty());assertTrue(c.folders.isEmpty());assertFalse(c.configured);assertEquals("",c.initial());}
 @Test public void emptySectionHasNoAutomaticChatsOrTabs(){SectionConfig c=new SectionConfig();SectionConfig.Section s=c.add("New");assertTrue(s.chats.isEmpty());assertEquals(0,s.flags);assertTrue(s.visibleTabs(Arrays.asList("tg:2")).isEmpty());s.general=true;assertTrue(s.visibleTabs(Collections.emptyList()).isEmpty());assertFalse(SectionConfig.includes(s,12,1,true,false,false));}
 @Test public void chatsOnlySectionHasNoFolderBar(){SectionConfig.Section s=new SectionConfig().add("Friends");s.include(10);s.include(-20);assertTrue(s.visibleTabs(Collections.emptyList()).isEmpty());assertTrue(SectionConfig.includes(s,10,0,false,false,false));assertFalse(SectionConfig.includes(s,11,1,false,false,false));}
 @Test public void oneFolderHasOnlyItsConfiguredTab(){SectionConfig.Section s=new SectionConfig().add("Games");s.tabs.add("tg:2");assertEquals(Arrays.asList("tg:2"),s.visibleTabs(Arrays.asList("tg:2","tg:3")));}
 @Test public void foldersRemainInPerSectionOrder(){SectionConfig.Section s=new SectionConfig().add("Games");s.tabs.addAll(Arrays.asList("tg:3","tg:2"));assertEquals(Arrays.asList("tg:3","tg:2"),s.visibleTabs(Arrays.asList("tg:2","tg:3")));}
 @Test public void mixedGeneralIsOptionalAndNeverInvented(){SectionConfig.Section s=new SectionConfig().add("Mix");s.include(7);s.tabs.add("tg:2");assertEquals(Arrays.asList("tg:2"),s.visibleTabs(Arrays.asList("tg:2")));s.general=true;assertEquals(Arrays.asList(SectionConfig.OWN,"tg:2"),s.visibleTabs(Arrays.asList("tg:2")));}
 @Test public void oneChatCanBelongToTwoIndependentSections(){SectionConfig c=new SectionConfig();SectionConfig.Section a=c.add("A"),b=c.add("B");a.include(42);b.include(42);a.exclude(42);assertFalse(SectionConfig.includes(a,42,1,true,false,false));assertTrue(SectionConfig.includes(b,42,1,true,false,false));}
 @Test public void sharedFolderCanBeDetachedWithoutDeletingSource(){SectionConfig c=new SectionConfig();SectionConfig.Section a=c.add("A"),b=c.add("B");SectionConfig.Folder f=c.addFolder("Local");a.tabs.addAll(Arrays.asList("tg:9",f.id));b.tabs.addAll(a.tabs);a.tabs.remove("tg:9");a.tabs.remove(f.id);assertEquals(2,b.tabs.size());assertNotNull(c.folders.get(f.id));}
 @Test public void restartPreservesNamesUnicodeIdsOrderAndLastFolder(){SectionConfig c=new SectionConfig();SectionConfig.Section a=c.add("Друзья 😀"),b=c.add("Игры");SectionConfig.Folder f=c.addFolder("Minecraft");a.icon="🎮";a.general=true;a.tabs.addAll(Arrays.asList("tg:17",f.id));a.lastFolder=f.id;a.include(Long.MIN_VALUE+7);a.exclude(-123);a.flags=1|4|64;c.defaultId=a.id;SectionConfig.move(c.sections,a,1);SectionConfig d=SectionConfig.decode(c.encode());assertEquals(b.id,d.sections.get(0).id);assertEquals(a.id,d.initial());assertEquals(a.icon,d.section(a.id).icon);assertEquals(a.tabs,d.section(a.id).tabs);assertEquals(a.lastFolder,d.section(a.id).lastFolder);assertEquals(a.chats,d.section(a.id).chats);assertEquals(a.excluded,d.section(a.id).excluded);assertEquals(a.flags,d.section(a.id).flags);assertEquals(f.token,d.folders.get(f.id).token);}
 @Test public void folderSelectionUsesStableKeyAfterReorderRenameOrServerDeletion(){SectionConfig.Section s=new SectionConfig().add("S");s.tabs.addAll(Arrays.asList("tg:2","tg:17"));s.lastFolder="tg:17";SectionConfig.move(s.tabs,"tg:17",-1);assertEquals("tg:17",SectionConfig.selectedTab(s,s.visibleTabs(Arrays.asList("tg:2","tg:17"))));assertEquals("tg:2",SectionConfig.selectedTab(s,s.visibleTabs(Arrays.asList("tg:2"))));assertEquals("tg:17",s.lastFolder);}
 @Test public void accountNamespacesAndConfigInstancesAreSeparate(){assertNotEquals(SectionConfig.accountNamespace(100),SectionConfig.accountNamespace(101));SectionConfig a=new SectionConfig(),b=new SectionConfig();a.add("A");assertTrue(b.sections.isEmpty());}
 @Test public void automaticRulesAreOptInWithExplicitPrecedence(){SectionConfig.Scope s=new SectionConfig.Scope();s.flags=1|64|128;assertTrue(SectionConfig.includes(s,1,1,true,false,false));assertFalse(SectionConfig.includes(s,2,1,false,false,false));assertFalse(SectionConfig.includes(s,3,1,true,false,true));s.include(3);assertTrue(SectionConfig.includes(s,3,1,false,true,true));s.exclude(3);assertFalse(SectionConfig.includes(s,3,1,true,false,false));}
 @Test public void localFolderDeletionRemovesAllLinksButNoChats(){SectionConfig c=new SectionConfig();SectionConfig.Section a=c.add("A"),b=c.add("B");SectionConfig.Folder f=c.addFolder("F");a.tabs.add(f.id);b.tabs.add(f.id);a.include(1);b.include(1);c.removeFolder(f.id);assertTrue(a.tabs.isEmpty());assertTrue(b.tabs.isEmpty());assertEquals(1,a.chats.size());assertEquals(1,b.chats.size());}
 @Test public void deletingAllSectionsDoesNotResetToAnInventedSection(){SectionConfig c=new SectionConfig();String id=c.add("A").id;c.defaultId=id;c.remove(id);SectionConfig d=SectionConfig.decode(c.encode());assertTrue(d.configured);assertTrue(d.sections.isEmpty());assertEquals("",d.initial());}
 @Test public void noArtificialSectionCapAndIndependentLocalTokens(){SectionConfig c=new SectionConfig();for(int i=0;i<150;i++)c.add("S"+i);Set<String> ids=new HashSet<>();for(SectionConfig.Section s:c.sections)assertTrue(ids.add(s.id));SectionConfig.Folder a=c.addFolder("A"),b=c.addFolder("B");assertNotEquals(a.id,b.id);assertNotEquals(a.token,b.token);SectionConfig d=SectionConfig.decode(c.encode());assertEquals(150,d.sections.size());assertTrue(d.addFolder("C").token>b.token);}
 @Test public void twoLocalPagesResolveIndependentScopes(){SectionConfig c=new SectionConfig();SectionConfig.Section s=c.add("S");SectionConfig.Folder a=c.addFolder("A"),b=c.addFolder("B");a.include(11);b.include(22);s.tabs.addAll(Arrays.asList(a.id,b.id));assertSame(a,c.scope(s.id,s.tabs.get(0)));assertSame(b,c.scope(s.id,s.tabs.get(1)));assertFalse(SectionConfig.includes(c.scope(s.id,b.id),11,0,false,false,false));assertTrue(SectionConfig.includes(c.scope(s.id,b.id),22,0,false,false,false));assertSame(s,c.scope(s.id,SectionConfig.OWN));}
 @Test public void unreadAndMuteRulesReevaluateWithoutChangingSavedMembership(){SectionConfig.Scope s=new SectionConfig.Scope();s.flags=1|32|64;assertTrue(SectionConfig.includes(s,1,1,true,false,false));assertFalse(SectionConfig.includes(s,1,1,false,false,false));assertFalse(SectionConfig.includes(s,1,1,true,true,false));assertTrue(s.chats.isEmpty());assertTrue(SectionConfig.includes(s,1,1,true,false,false));}
 @Test(expected=IllegalArgumentException.class) public void futureSchemaIsNotSilentlyOverwritten(){SectionConfig.decode("schema=999\n");}
 @Test(expected=IllegalArgumentException.class) public void emptyNameIsRejected(){new SectionConfig().add("  ");}
}
